import * as R from './recall-core.js';import * as C from './core.js';import {WORDS} from './data.js';import {createSpeech} from './speech.js';import {voiceSelect} from './voice-client.js';
export function createRecall({esc,head,button,getState,commit,render,go,toast,stopAudio,openWord,openNew}){
 let mode='home',session=null,draft='',pairId='p01',pairIndex=0,pairStage='intro',pairHelp=false,pairResult=null,pairDraft='',pairDate=C.today(),historyId=null;
 const speech=createSpeech({toast}),wmap={get:id=>C.wordsFor(getState()).find(w=>w.id===id)};
 function move(){go('recall');globalThis.window?.scrollTo({top:0,behavior:'instant'});}
 const stat=r=>r?`答题时未用提示 ${r.independent} 次 · 提示后匹配 ${r.assisted} 次 · 未匹配 ${r.unmatched} 次`:'还没有练习记录';
 function home(){const s=getState(),date=C.today(),due=R.dueRecall(s,date),words=Object.entries(s.recall?.words||{});return head('REMEMBER, AT YOUR OWN PACE','让记忆，经得起明天','先试着回忆，再选择需要的提示。每一次真实表现，都值得留下。')+`<section class="panel glass recall-panel recall-entry"><div class="panel-head"><h2>先盲测，再看词卡</h2><span class="pill blue">${due.length} 个到期</span></div><p>一次最多 5 词，用中文回忆指定卡片的英文。今天看过普通词卡、点过提示或重做过的题，会与未用提示的结果分开。</p><div class="actions">${button(due.length?'开始到期盲测':'用已学词做一次起步自测','recall-start')}${button('开始跟踪已有词汇','recall-track','','btn secondary')}</div><p class="caption">已有 ${words.length} 词开始跟踪。旧数据不会补造测试成绩；首次跟踪的词最早明天进入延迟测试。当天自测不会算成隔天通过。</p></section><section class="panel glass recall-panel"><h2>容易混的，放在一起辨一辨</h2><p>先分别接触两个词，再用具体句子对照。答题时重新看对照，会记为借助提示。</p><div class="recall-pairs">${R.PAIRS.map(p=>`<div class="recall-pair-card"><strong lang="en">${p.words.map(w=>esc(w.word)).join(' / ')}</strong><p class="caption">${p.words.filter(w=>s.cards[w.id]).length}/2 词已接触 · ${stat(s.recall?.pairs[p.id])}</p>${button(R.readyPair(s,p)?'看对照，开始练习':'先分别认识这两个词','recall-pair',`data-pair="${p.id}"`,'btn secondary')}</div>`).join('')}</div></section><section class="panel glass recall-panel"><h2>回忆留下的脚印</h2><p class="caption">“答题时没用提示”只描述那次测试；日期是历史表现，不表示永久掌握。</p>${words.sort((a,b)=>(b[1].events.at(-1)?.date||b[1].anchor).localeCompare(a[1].events.at(-1)?.date||a[1].anchor)).slice(0,12).map(([id,r])=>`<div class="recall-history-row"><strong lang="en">${esc(wmap.get(id).word)}</strong><p class="caption">${stat(r)} · ${r.due} 再试</p>${button('看提示与延迟记录','recall-history',`data-word="${id}"`,'text-btn')}</div>`).join('')||'<p>先学一个词，之后这里会慢慢长出你的记忆记录。</p>'}</section>`;}
 function history(){const s=getState(),w=wmap.get(historyId),r=s.recall?.words[historyId];if(!w||!r)return home();return head('LITTLE TRACES OF RECALL',esc(w.word),'这些记录描述具体表现，不代表测定了记忆强度。')+`<section class="panel glass recall-panel"><p>${esc(w.meaning)}</p><p class="caption">${r.anchor} 开始跟踪 · 下次 ${r.due}</p><div class="recall-milestones">${[['当天自测',r.todayPassed],['隔天及以后',r.nextPassed],['第7天及以后',r.weekPassed]].map(([label,date])=>`<div class="${date?'done':''}"><strong>${label}</strong><span>${date||'还没有独立匹配记录'}</span></div>`).join('')}</div><p class="caption">里程碑需要匹配参考词形且未用提示；两个延迟节点必须在不同日期完成。同一天看到反馈后重做，不会补成独立通过。</p><p>${stat(r)}</p>${[...r.events].reverse().map(e=>`<div class="recall-history-row"><span class="pill ${e.match?'blue':'warm'}">${e.match?(e.hints.length?'提示后匹配':'答题时未用提示'):'未匹配本卡词形'}</span><p>${e.date} · 跟踪第 ${C.daysBetween(r.anchor,e.date)} 天</p><p class="caption">${e.hints.length?'使用线索：'+e.hints.map(h=>R.HINTS[h]).join('、'):'本次未点提示'}</p></div>`).join('')||'<p>目前只有跟踪日期，还没有测试结果。</p>'}<p class="caption">保留最近 6 次明细及累计次数。</p></section>${button('返回记忆巩固','recall-home','','btn secondary')}`;}
 function question(){if(!session)return home();const id=session.ids[session.index];if(!id)return head('A LITTLE RECALL, A LITTLE PROGRESS','这轮回忆，已经留下脚印','结果已保存在这台设备。提示后练对，也是下一次独立想起来的准备。')+`<section class="panel glass recall-panel"><p>本轮完成 ${session.results.length} 题。</p><p>答题时未用提示：${session.results.filter(e=>e.match&&!e.hints.length).length} · 提示后匹配：${session.results.filter(e=>e.match&&e.hints.length).length} · 未匹配本卡词形：${session.results.filter(e=>!e.match).length}</p>${button('返回记忆巩固','recall-home')}</section>`;
  const s=getState(),w=wmap.get(id),r=s.recall.words[id],hints=R.activeHints(s,id),shown=r.cueDate===C.today()?r.cues:[],result=session.result;
  return head('CLOSE THE CARD, TRY TO RECALL',session.delayed?'隔天及以后，再独立试一次':'今天先试一次，不算延迟通过',`${session.index+1} / ${session.ids.length} · 根据中文，回忆这张卡片的英文词形`)+`<section class="panel glass recall-panel recall-question"><h2>${esc(w.meaning)}</h2><p class="caption">${esc(w.topic)} · 大小写不影响结果。近义表达可能合理；这里只核对指定卡片词形。</p>${result?`<div class="feedback"><strong>${result.match?(result.hints.length?'提示后匹配了，继续慢慢练。':'这次答题没有使用提示。'):'暂未匹配这张卡片的词形。'}</strong><p>你的作答：<span lang="en">${esc(session.answer||'未填写')}</span></p><p>参考词形：<strong lang="en">${esc(w.word)}</strong></p><p>${result.hints.length?'本次线索：'+result.hints.map(h=>R.HINTS[h]).join('、'):'本次未点提示。'} 下次安排：${r.due}</p>${!result.match?button('我需要练这个词形，放入拼写复习','recall-mistake','','btn secondary'):''}</div><div class="actions">${button('下一词','recall-next')}${button('看这个词的记忆记录','recall-history',`data-word="${id}"`,'btn ghost')}</div>`:`<form id="recall-answer-form"><div class="field"><label for="recall-answer">试着写出英文</label><input id="recall-answer" name="answer" lang="en" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="100" value="${esc(draft)}"></div><button class="btn" type="submit">核对本卡词形</button></form><div class="recall-hints"><p>卡住也没关系，选一点帮助：</p><div class="actions">${button('给首字母','recall-hint','data-hint="initial"','btn secondary')}${button('听发音','recall-audio','','btn secondary')}${button('看完整答案','recall-hint','data-hint="reveal"','btn ghost')}</div><div class="speech-options">${voiceSelect()}</div><p class="caption" data-speech-status role="status"></p>${shown.includes('initial')?`<p class="recall-clue" lang="en">${esc(R.firstHint(w.word))}</p>`:''}${shown.includes('reveal')?`<p class="recall-clue" lang="en">${esc(w.word)}</p><p class="caption">看过答案后可以重写一次，将记为提示后练习。</p>`:''}<p class="caption">${hints.length?'本次已用线索：'+hints.map(h=>R.HINTS[h]).join('、'):'目前还没有使用提示。'}</p></div>`}</section>${button('返回记忆巩固','recall-home','','text-btn')}`;
 }
 function pairView(){const s=getState(),p=R.PAIRS.find(p=>p.id===pairId),ready=R.readyPair(s,p),comparison=`<div class="recall-comparison">${p.words.map(w=>`<div><strong lang="en">${esc(w.word)}</strong><p>${esc(w.meaning)}</p></div>`).join('')}</div><p>${esc(p.note)}</p>`;
  if(pairStage==='intro'||!ready)return head('SIMILAR WORDS, CLEARER MEANINGS',p.words.map(w=>esc(w.word)).join(' / '),ready?'用两句具体的话，慢慢分清。':'先分别接触两个词，再开放对照题。')+`<section class="panel glass recall-panel">${ready?comparison:`<p>这组还没准备好。先分别学习，之后再回来比较。</p>${p.words.map(w=>`<div class="recall-history-row"><strong lang="en">${esc(w.word)}</strong><p>${s.cards[w.id]?'已接触':'尚未记录接触'}</p>${button('单独学习这个词','recall-learn-word',`data-word="${w.id}"`,'btn secondary')}</div>`).join('')}`}${ready?button('隐藏对照，开始第1句','recall-pair-start'):''}<p class="caption">本组为原创语境练习，不是雅思真题，也不推断永久掌握。</p></section>${button('返回记忆巩固','recall-home','','text-btn')}`;
  if(pairIndex>=p.questions.length)return head('A LITTLE LESS CONFUSION','这一组，认真分辨过了','两词的辨析记录与延迟测试分别保存。')+`<section class="panel glass recall-panel"><p>${stat(s.recall.pairs[p.id])}</p>${button('返回记忆巩固','recall-home')}</section>`;
  const q=p.questions[pairIndex];return head('CHOOSE THE WORD THAT FITS','这句话，选哪个更贴切？',`${pairIndex+1} / ${p.questions.length} · 原创语境练习`)+`<section class="panel glass recall-panel recall-question"><p class="recall-sentence" lang="en">${esc(q.sentence)}</p><p>${esc(q.chinese)}</p><form id="recall-pair-form"><fieldset class="quiz-question"><legend>选择本题语境对应的词</legend>${p.words.map(w=>`<label class="quiz-option"><input type="radio" name="answer" value="${esc(w.word)}" ${pairResult?'disabled':''} ${pairDraft===w.word?'checked':''} required><span lang="en">${esc(w.word)}</span></label>`).join('')}</fieldset>${pairResult?'':'<button class="btn" type="submit">核对这一句</button>'}</form>${pairResult?`<div class="feedback"><strong>${pairResult.match?'本次选对了。':'再对照一下这句话。'}</strong><p>参考：${esc(q.answer)}</p><p>${esc(p.note)}</p><p class="caption">${pairResult.supported?'本次使用过对照或当天已看过本题反馈，记录为提示后练习。':'本次答题未重新打开对照，不代表延迟记忆已通过。'}</p></div>${button('下一句','recall-pair-next')}`:`${button(pairHelp?'收起对照':'再看一次对照','recall-pair-help','','text-btn')}${pairHelp?comparison:''}`}</section>${button('返回记忆巩固','recall-home','','text-btn')}`;
 }
 function view(){if((session&&session.date!==C.today())||(mode==='pair'&&pairDate!==C.today())){session=null;mode='home';}return mode==='test'?question():mode==='pair'?pairView():mode==='history'?history():home();}
 const leave=()=>speech.stop();
 function openPair(id,index=0,retry=false){leave();stopAudio();pairId=id;pairDate=C.today();pairDraft='';pairIndex=index;pairStage=retry?'question':'intro';pairHelp=false;pairResult=null;mode='pair';move();}
 function act(action,el){if(!action.startsWith('recall-'))return false;
  if(action==='recall-home'){leave();stopAudio();mode='home';move();}
  if(action==='recall-track'){const count=commit(s=>R.startTracking(s));toast(`已跟踪 ${count} 个已接触词，历史测试成绩保持空白。`);render();}
  if(action==='recall-start'){leave();stopAudio();commit(s=>R.startTracking(s));const s=getState(),ids=R.practiceIds(s);if(!ids.length){toast('先认识一个词，之后就可以开始跟踪。');openNew();return true;}session={ids,index:0,date:C.today(),delayed:R.dueRecall(s).length>0,result:null,results:[],answer:''};draft='';mode='test';move();}
  if(action==='recall-hint'&&session&&!session.result){commit(s=>R.hint(s,session.ids[session.index],el.dataset.hint));render();}
  if(action==='recall-audio'&&session&&!session.result){const current=session,at=current.index,id=current.ids[at];stopAudio();speech.speak(wmap.get(id).word,{rate:.85,onstart:()=>{if(session!==current||current.index!==at||current.result)return;commit(s=>R.hint(s,id,'audio'));render();}});}
  if(action==='recall-next'&&session?.result){leave();stopAudio();session.index++;session.result=null;session.answer='';draft='';render();}
  if(action==='recall-mistake'&&session?.result&&!session.result.match){commit(s=>R.addRecallMistake(s,session.ids[session.index],session.answer));toast('已放入拼写复习。');}
  if(action==='recall-history'){leave();stopAudio();historyId=el.dataset.word;mode='history';move();}
  if(action==='recall-pair')openPair(el.dataset.pair);
  if(action==='recall-learn-word'){leave();openWord(el.dataset.word);}
  if(action==='recall-pair-start'){pairStage='question';pairDraft='';pairDate=C.today();pairIndex=0;pairHelp=false;pairResult=null;render();}
  if(action==='recall-pair-help'){if(!pairHelp)commit(s=>R.pairHint(s,pairId,pairIndex));pairHelp=!pairHelp;render();}
  if(action==='recall-pair-next'&&pairResult){pairIndex++;pairDraft='';pairResult=null;pairHelp=false;render();}
  return true;
 }
 function submit(form,values){if(!['recall-answer-form','recall-pair-form'].includes(form.id))return false;try{if(form.id==='recall-answer-form'){if(!session||session.result)return true;if(session.date!==C.today())throw Error('日期已变化，请重新开始今天的测试。');session.answer=values.answer||'';session.result=commit(s=>R.answerRecall(s,session.ids[session.index],session.answer));session.results.push(session.result);leave();stopAudio();render();}else{if(pairResult)return true;if(pairDate!==C.today())throw Error('日期已变化，请重新开始今天的辨析。');pairDraft=values.answer;pairResult=commit(s=>R.pairAnswer(s,pairId,pairIndex,values.answer,pairHelp));render();}}catch(e){toast(e.message);}return true;}
 function input(e){if(e.target.id==='recall-answer')draft=e.target.value;if(e.target.matches?.('#recall-pair-form input[name=answer]'))pairDraft=e.target.value;}
 return {view,act,submit,input,leave,openPair,reset(){leave();mode='home';session=null;},entry:()=>`<section class="panel glass recall-panel recall-entry"><h2>让今天记住的，明天再试一次</h2><p>隔天盲测、易混词对照和提示记录，都放进记忆巩固。</p><a href="#recall" class="btn secondary">打开记忆巩固 · ${R.dueRecall(getState()).length} 词到期</a></section>`};
}
